mapper.select:
SELECT o.ID AS id, o.BIZ_TYPE AS bizType, o.BIZ_ID AS bizId, o.TOPIC_OR_ENDPOINT AS topicOrEndpoint, o.PAYLOAD_JSON AS payloadJson, o.MSG_STATUS AS msgStatus, o.RETRY_COUNT AS retryCount, o.NEXT_RETRY_TIME_MS AS nextRetryTimeMs, o.LAST_ERROR AS lastError, o.IDEMPOTENT_KEY AS idempotentKey, o.ENV_CODE AS envCode, o.DELETED AS deleted, o.CREATE_USER AS createUser, o.CREATE_TIME AS createTime, o.UPDATE_USER AS updateUser, o.UPDATE_TIME AS updateTime FROM AST_FLOW_MSG_OUTBOX o WHERE (o.DELETED = 0 OR o.DELETED IS NULL)
AND o.BIZ_TYPE = #{req.bizType}
AND o.BIZ_ID = #{req.bizId}
AND o.MSG_STATUS = #{req.msgStatus}
AND o.IDEMPOTENT_KEY = #{req.idempotentKey}
AND o.ENV_CODE = #{req.envCode}
ORDER BY o.UPDATE_TIME DESC, o.ID DESC
